ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
  jsonrpc: "2.0",
  id: vars.mcpId,
  result: {
    protocolVersion: "2024-11-05",
    capabilities: {
      tools: { listChanged: false }
    },
    serverInfo: {
      name: "mule-app-governance-mcp",
      version: "1.0.0"
    }
  }
}

%dw 2.0
output application/json
---
{
  jsonrpc: "2.0",
  id: vars.mcpId,
  result: {
    tools: [
      {
        name: "get-compliance-report",
        description: "Get compliance status for Mule applications in a given environment. Returns compliant and non-compliant apps with issue details.",
        inputSchema: {
          "type": "object",
          properties: {
            appName: { "type": "string", description: "Application name to filter (use 'all' for all apps)" },
            environment: { "type": "string", description: "Anypoint environment name (e.g. Production, Sandbox)" }
          },
          required: []
        }
      },
      {
        name: "write-ado-log",
        description: "Write an Application Data Observability (ADO) alert log entry to Splunk. Triggers a PagerDuty incident within 15 minutes if criteria are met.",
        inputSchema: {
          "type": "object",
          properties: {
            severity: { "type": "string", description: "Severity level: LOW, MEDIUM, HIGH, or CRITICAL" },
            message: { "type": "string", description: "Log message describing the alert" },
            source: { "type": "string", description: "Source system name" }
          },
          required: ["severity", "message"]
        }
      }
    ]
  }
}

%dw 2.0
output application/json
var toolResult = payload
---
{
  jsonrpc: "2.0",
  id: vars.mcpId,
  result: {
    content: [{ "type": "text", text: write(toolResult, "application/json") }]
  }
}

%dw 2.0
output application/json
---
{
  jsonrpc: "2.0",
  id: vars.mcpId,
  error: { code: -32601, message: "Method not found: " ++ vars.mcpMethod }
}

ee:variables.ee:set-variable:
%dw 2.0
output application/java
var allEnvs = payload.data default []
var reqEnvLower = lower(vars.reqEnvironment)
var exactEnvMatch = allEnvs filter (lower($.name) == reqEnvLower)
var fuzzyEnvMatch = allEnvs filter (lower($.name) contains reqEnvLower or reqEnvLower contains lower($.name))
var envMatches = if (!isEmpty(exactEnvMatch)) exactEnvMatch else fuzzyEnvMatch
---
(envMatches[0].id) default ""

%dw 2.0
output application/java
var allEnvs = payload.data default []
var reqEnvLower = lower(vars.reqEnvironment)
var exactEnvMatch = allEnvs filter (lower($.name) == reqEnvLower)
var fuzzyEnvMatch = allEnvs filter (lower($.name) contains reqEnvLower or reqEnvLower contains lower($.name))
var envMatches = if (!isEmpty(exactEnvMatch)) exactEnvMatch else fuzzyEnvMatch
---
(envMatches[0].name) default vars.reqEnvironment

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
  status: "UP",
  service: "muleops-governance-mcp",
  version: "1.0.0",
  tools: ["get-compliance-report", "write-ado-log"],
  timestamp: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss'Z'"}
}
